import{_ as e,c as n,o as a,a1 as l}from"./chunks/framework.C3Hmo1as.js";const c=JSON.parse('{"title":"AI Coding Agent 使用心得","description":null,"frontmatter":{"title":"AI Coding Agent 使用心得","description":null,"date":"2026-04-17T00:00:00.000Z","tags":["Coding Agent"]},"headers":[],"relativePath":"ai/ai-coding-agent.md","filePath":"ai/ai-coding-agent.md"}'),o={name:"ai/ai-coding-agent.md"};function r(i,t,s,g,d,h){return a(),n("div",null,[...t[0]||(t[0]=[l('<blockquote><p>很多人在用“大炮轰蚊子”，而且是用“最贵的金弹头”去轰一群蚊子。</p></blockquote><h2 id="agent-模式-vs-自动化脚本模式" tabindex="-1">Agent 模式 vs. 自动化脚本模式 <a class="header-anchor" href="#agent-模式-vs-自动化脚本模式" aria-label="Permalink to &quot;Agent 模式 vs. 自动化脚本模式&quot;">​</a></h2><p>你说得非常对，这其实是目前很多开发者在使用 <strong>AI Coding Agent</strong>（如 Claude Code, Cursor, Windsurf）时的一个典型“消费误区”。</p><p>简单来说，他的意思是：<strong>很多人在用“大炮轰蚊子”，而且是用“最贵的金弹头”去轰一群蚊子。</strong></p><p>以下是这段话的详细拆解：</p><hr><h2 id="_1-核心矛盾-agent-模式-vs-自动化脚本模式" tabindex="-1">1. 核心矛盾：Agent 模式 vs. 自动化脚本模式 <a class="header-anchor" href="#_1-核心矛盾-agent-模式-vs-自动化脚本模式" aria-label="Permalink to &quot;1. 核心矛盾：Agent 模式 vs. 自动化脚本模式&quot;">​</a></h2><p>对比两种处理大量同类文件（比如给 100 个代码文件加注释，或者重构 50 个接口）的方式：</p><h3 id="模式-a-直接让-coding-模型处理-claude-code-方式" tabindex="-1"><strong>模式 A：直接让 Coding 模型处理（Claude Code 方式）</strong> <a class="header-anchor" href="#模式-a-直接让-coding-模型处理-claude-code-方式" aria-label="Permalink to &quot;**模式 A：直接让 Coding 模型处理（Claude Code 方式）**&quot;">​</a></h3><ul><li><strong>做法：</strong> 你对 Claude Code 说：“帮我把这个文件夹里所有的 Python 文件都改成异步调用。”</li><li><strong>代价：</strong> Claude 会反复读取文件、思考、尝试修改、运行测试、报错、再读取。因为 Claude Code 这种 Agent 是为了解决<strong>复杂逻辑</strong>设计的，它每一步都会携带大量的上下文（Context Window），导致 Token 消耗极快。</li><li><strong>结果：</strong> 还没改完几个文件，你的额度（套餐）就见底了。</li></ul><h3 id="模式-b-编写-python-脚本-调用-llm-api-这种更聪明" tabindex="-1"><strong>模式 B：编写 Python 脚本 + 调用 LLM API（这种更聪明）</strong> <a class="header-anchor" href="#模式-b-编写-python-脚本-调用-llm-api-这种更聪明" aria-label="Permalink to &quot;**模式 B：编写 Python 脚本 + 调用 LLM API（这种更聪明）**&quot;">​</a></h3><ul><li><strong>做法：</strong> 你先花 5 分钟让 Claude 帮你写一个 <strong>Python 脚本</strong>。这个脚本的功能是：遍历文件夹 -&gt; 读取单个文件内容 -&gt; 调用便宜的 API（如 Claude 3.5 Haiku 或 GPT-4o-mini）-&gt; 按照既定模板处理 -&gt; 保存。</li><li><strong>代价：</strong> 你只在编写脚本时消耗了一点点高性能模型的 Token。后续的大规模处理运行的是本地代码，API 调用也是按需付费，没有 Agent 模式下沉重的“思考成本”。</li><li><strong>结果：</strong> 处理 1000 个文件可能也就花几块钱，而且速度极快，完全可控。</li></ul><hr><h2 id="_2-为什么这样是-没底-且-不可行" tabindex="-1">2. 为什么这样是“没底”且“不可行”？ <a class="header-anchor" href="#_2-为什么这样是-没底-且-不可行" aria-label="Permalink to &quot;2. 为什么这样是“没底”且“不可行”？&quot;">​</a></h2><ul><li><strong>没底（成本不可控）：</strong> Agent 模式是“黑盒”操作。你不知道它为了改一个文件会反复读取多少次上下文。对于同质化的重复劳动，Agent 的智能是一种浪费。</li><li><strong>不可行（规模化难题）：</strong> * <strong>上下文溢出：</strong> 如果文件很多，Agent 的对话上下文会越来越长，最后导致模型“变笨”或者报错。 <ul><li><strong>效率低下：</strong> 脚本可以多线程并发处理，而 Agent 通常是一个一个文件磨洋工。</li></ul></li></ul><hr><h2 id="_3-总结" tabindex="-1">3. 总结 <a class="header-anchor" href="#_3-总结" aria-label="Permalink to &quot;3. 总结&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">直接用 Claude Code 处理多文件</th><th style="text-align:left;">Python 脚本 + LLM API</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>适用场景</strong></td><td style="text-align:left;">解决复杂的、跨文件的逻辑 Bug</td><td style="text-align:left;">处理大量同类、结构化的任务</td></tr><tr><td style="text-align:left;"><strong>成本消耗</strong></td><td style="text-align:left;"><strong>极高</strong>（全量上下文 + 高级模型费率）</td><td style="text-align:left;"><strong>极低</strong>（仅针对目标数据付费 + 低价模型）</td></tr><tr><td style="text-align:left;"><strong>可控性</strong></td><td style="text-align:left;">较低（AI 可能自由发挥）</td><td style="text-align:left;">极高（逻辑由 Python 代码锁定）</td></tr><tr><td style="text-align:left;"><strong>建议</strong></td><td style="text-align:left;">适合“攻坚战”</td><td style="text-align:left;">适合“扫荡战”</td></tr></tbody></table><h2 id="品味优先" tabindex="-1">品味优先 <a class="header-anchor" href="#品味优先" aria-label="Permalink to &quot;品味优先&quot;">​</a></h2><p>AI时代，代码变便宜了</p><p>变贵的是什么？</p><ul><li>品味</li><li>理解用户</li><li>讲故事</li></ul><p>全是文科生的强项</p>',23)])])}const p=e(o,[["render",r]]);export{c as __pageData,p as default};
